-- Remove Teddy Bear

INSERT INTO songVersion (songId, versionId, operationId, internalDescription)
SELECT
    (SELECT songId
FROM (
    SELECT
        songId,
        COUNT(*) OVER () AS total_count
    FROM (
        SELECT
            s.songId,
            o.internalTitle AS operation,
            ROW_NUMBER() OVER (
                PARTITION BY s.songId
                ORDER BY va.ancestorSortOrder DESC
            ) AS rn
        FROM song s
        JOIN songVersion sv ON sv.songId = s.songId
        JOIN operation o ON o.operationId = sv.operationId
        JOIN _derived_versionAncestor va ON va.ancestorId = sv.versionId
        WHERE va.versionId = (
            SELECT v.versionId
            FROM version v
            JOIN mix m ON m.mixId = v.mixId
            WHERE m.internalTitle = 'Phoenix'
            AND v.internalTitle = 'v2.12.0'
        )
        AND LOWER(s.internalTitle) = LOWER('Teddy Bear')
        AND s.cutId = (SELECT cutId FROM cut WHERE internalTitle = 'Full Song')
    )
    WHERE rn = 1
    AND operation != 'DELETE'
)
WHERE total_count = 1),
    (SELECT versionId FROM version
     WHERE mixId = (SELECT mixId FROM mix WHERE internalTitle = 'Phoenix 2')
     AND internalTitle = 'v1.00.0'),
    (SELECT operationId FROM operation WHERE internalTitle = 'DELETE'),
    NULL;

INSERT INTO chartVersion (chartId, versionId, operationId, internalDescription)
SELECT
  sub.chartId,
  (SELECT versionId FROM version
   WHERE mixId = (SELECT mixId FROM mix WHERE internalTitle = 'Phoenix 2')
   AND internalTitle = 'v1.00.0'),
  (SELECT operationId FROM operation WHERE internalTitle = 'DELETE'),
  NULL
FROM (
  SELECT
    crv.chartId,
    cv.operationId,
    ROW_NUMBER() OVER(PARTITION BY crv.chartId ORDER BY v.sortOrder DESC, v2.sortOrder DESC) as rn
  FROM chartRatingVersion crv
  JOIN chart c ON crv.chartId = c.chartId
  JOIN chartVersion cv ON cv.chartId = c.chartId
  JOIN chartRating cr on crv.chartRatingId = cr.chartRatingId
