  JOIN version v2 ON crv.versionId = v2.versionId
  WHERE v.mixId NOT IN (2, 8)
  AND v2.mixId NOT IN (2, 8)
  AND c.songId = (SELECT songId
FROM (
    SELECT
        songId,
        COUNT(*) OVER () AS total_count
    FROM (
        SELECT
            s.songId,
            o.internalTitle AS operation,
            ROW_NUMBER() OVER (
                PARTITION BY s.songId
                ORDER BY va.ancestorSortOrder DESC
            ) AS rn
        FROM song s
        JOIN songVersion sv ON sv.songId = s.songId
        JOIN operation o ON o.operationId = sv.operationId
        JOIN _derived_versionAncestor va ON va.ancestorId = sv.versionId
        WHERE va.versionId = (
            SELECT v.versionId
            FROM version v
            JOIN mix m ON m.mixId = v.mixId
            WHERE m.internalTitle = 'Phoenix'
            AND v.internalTitle = 'v2.12.0'
        )
        AND LOWER(s.internalTitle) = LOWER('Teddy Bear')
        AND s.cutId = (SELECT cutId FROM cut WHERE internalTitle = 'Full Song')
    )
    WHERE rn = 1
    AND operation != 'DELETE'
)
WHERE total_count = 1)
  AND v.versionId != (SELECT versionId FROM version
   WHERE mixId = (SELECT mixId FROM mix WHERE internalTitle = 'Phoenix 2')
   AND internalTitle = 'v1.00.0')
) AS sub
WHERE rn = 1
AND operationId != (SELECT operationId FROM operation WHERE internalTitle = 'DELETE');



